<script setup lang="ts">
import {ref,reactive,computed,onMounted} from 'vue';
import {useI18n} from 'vue-i18n';
import {request} from '../crm-api';
import {materialPhoto,type ApiProduct} from '../api';
const props=defineProps<{admin:boolean}>();const emit=defineEmits<{updated:[]}>();
const {locale}=useI18n();const tx=(z:string,e:string)=>locale.value==='zh'?z:e;
type Product=ApiProduct&{published:boolean;image_url:string;image_urls:string[];unit:string;width_min:number|null;width_max:number|null;height_min:number|null;height_max:number|null;colors:string[];controls:string[]};
const products=ref<Product[]>([]),query=ref(''),chosen=ref<number|null>(null),busy=ref(false),error=ref(''),notice=ref(''),adding=ref(false);
const blank=()=>({name_zh:'',name_en:'',material_zh:'',material_en:'',description_zh:'',description_en:'',category:'aluminium',image_url:'',image_urls:[] as string[],sample:true,published:false,unit:'mm',width_min:null as number|null,width_max:null as number|null,height_min:null as number|null,height_max:null as number|null});
const form=reactive(blank()),colors=ref(''),controls=ref('');
const filtered=computed(()=>products.value.filter(p=>[p.name_en,p.name_zh,p.category].join(' ').toLowerCase().includes(query.value.toLowerCase())));
const previewIndex=ref(0);
const preview=computed(()=>form.image_urls[previewIndex.value]||form.image_urls[0]||form.image_url||'');
function cover(index:number){const [url]=form.image_urls.splice(index,1);form.image_urls.unshift(url);form.image_url=url;previewIndex.value=0}
function removeImage(index:number){form.image_urls.splice(index,1);form.image_url=form.image_urls[0]||'';previewIndex.value=0}
function choose(p:Product){previewIndex.value=0;chosen.value=p.id;adding.value=false;Object.assign(form,blank(),p,{image_urls:[...(p.image_urls||[])]});colors.value=p.colors.join(', ');controls.value=p.controls.join(', ');error.value='';notice.value=''}
function add(){previewIndex.value=0;chosen.value=null;adding.value=true;Object.assign(form,blank());colors.value='';controls.value='';notice.value='';error.value=''}
async function load(){products.value=await request<Product[]>('admin/products');if(!adding.value){const p=products.value.find(p=>p.id===chosen.value)||products.value[0];if(p)choose(p)}}
async function save(){busy.value=true;error.value='';try{const values={...form,image_url:form.image_urls[0]||'',width_min:form.width_min==null||String(form.width_min)===''?null:Number(form.width_min),width_max:form.width_max==null||String(form.width_max)===''?null:Number(form.width_max),height_min:form.height_min==null||String(form.height_min)===''?null:Number(form.height_min),height_max:form.height_max==null||String(form.height_max)===''?null:Number(form.height_max),colors:colors.value.split(/[,，\n]/).map(s=>s.trim()).filter(Boolean),controls:controls.value.split(/[,，\n]/).map(s=>s.trim()).filter(Boolean)};const p=await request<Product>(chosen.value?`admin/products/${chosen.value}`:'admin/products',values);chosen.value=p.id;adding.value=false;await load();notice.value=tx('已保存。官网重新加载后显示同一产品资料。','Saved. Reload the website to see the same product details.');emit('updated')}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
async function upload(event:Event){const input=event.target as HTMLInputElement,files=Array.from(input.files||[]);if(!files.length)return;if(form.image_urls.length+files.length>12){error.value=tx('最多12张图片。','Up to 12 images.');input.value='';return}if(files.some(file=>file.size>5*1024*1024||!['image/png','image/jpeg','image/webp'].includes(file.type))){error.value=tx('每张请选择5MB以内PNG、JPEG或WebP。','Each image must be PNG, JPEG or WebP, up to 5 MB.');input.value='';return}busy.value=true;error.value='';try{for(const file of files){const data=await new Promise<string>((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=()=>reject(new Error('Image could not be read'));r.readAsDataURL(file)});const result=await request<{image_url:string}>('admin/product-images',{data,content_type:file.type});form.image_urls.push(result.image_url);form.image_url=form.image_urls[0]}notice.value=tx('图片已加入图集，保存产品后应用。','Images added to the gallery. Save the product to apply them.')}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false;input.value=''}}

onMounted(async()=>{try{await load()}catch(e){error.value=e instanceof Error?e.message:String(e)}});
</script>
<template>
<div class="product-manager">
<aside class="catalog-list card"><div class="catalog-title"><h2>{{tx('产品维护','Products')}}</h2><button v-if="admin" type="button" @click="add" :disabled="busy">＋ {{tx('新增','Add')}}</button></div><label>{{tx('搜索产品','Search products')}}<input v-model="query" type="search" /></label><p class="catalog-hint">{{tx('官网与报价共用此目录','Shared by the website and quotations')}}</p><button v-for="p in filtered" :key="p.id" type="button" class="catalog-item" :class="{selected:chosen===p.id}" @click="choose(p)"><img :src="materialPhoto(p)" alt=""/><span><strong>{{locale==='zh'?p.name_zh:p.name_en}}</strong><small>{{p.published?tx('官网展示','Visible on website'):tx('未展示','Hidden from website')}} · #{{p.id}}</small></span></button><p v-if="!filtered.length">{{tx('没有匹配的产品','No matching products')}}</p></aside>
<section class="catalog-editor card" v-if="chosen||adding"><div class="catalog-title"><div><p class="catalog-hint">{{adding?tx('新产品','NEW PRODUCT'):`PRODUCT #${chosen}`}}</p><h2>{{adding?tx('新增产品','Add product'):(locale==='zh'?form.name_zh:form.name_en)}}</h2></div><span class="catalog-hint">{{admin?tx('管理员可编辑','Administrator access'):tx('销售只读','Read-only for sales')}}</span></div>
<p v-if="error" class="alert" role="alert">{{error}}</p><p v-if="notice" class="success" role="status">{{notice}}</p>
<form @submit.prevent="save"><div class="catalog-overview"><div class="product-photo-preview"><img v-if="preview" :src="preview" :alt="locale==='zh'?form.name_zh:form.name_en"/><label v-if="admin" class="image-upload">{{tx('添加产品图片','Add product images')}}<input type="file" multiple accept="image/png,image/jpeg,image/webp" @change="upload" :disabled="busy"/></label><small>{{tx('PNG / JPEG / WebP · 最大5MB','PNG / JPEG / WebP · Up to 5 MB')}}</small><div class="gallery-editor"><article v-for="(url,index) in form.image_urls" :key="url"><button type="button" class="gallery-thumb" :class="{active:previewIndex===index}" :aria-label="tx(`预览第${index+1}张产品图`,`Preview product image ${index+1}`)" :aria-pressed="previewIndex===index" @click="previewIndex=index"><img :src="url" alt=""/></button><small>{{index===0?tx('封面','Cover'):`${index+1}`}}</small><div v-if="admin"><button v-if="index>0" type="button" class="secondary" @click="cover(index)">{{tx('设为封面','Set cover')}}</button><button type="button" class="secondary" @click="removeImage(index)" :aria-label="tx(`移除第${index+1}张图片`,`Remove image ${index+1}`)">{{tx('移除','Remove')}}</button></div></article></div></div><div class="catalog-fields"><h3>{{tx('基本资料','Product details')}}</h3><div class="field-pair"><label>{{tx('中文名称','Chinese name')}}<input v-model="form.name_zh" required maxlength="160" :readonly="!admin"/></label><label>{{tx('英文名称','English name')}}<input v-model="form.name_en" required maxlength="160" :readonly="!admin"/></label></div><div class="field-pair"><label>{{tx('中文材质','Material in Chinese')}}<input v-model="form.material_zh" required maxlength="100" :readonly="!admin"/></label><label>{{tx('英文材质','Material in English')}}<input v-model="form.material_en" required maxlength="100" :readonly="!admin"/></label></div><label>{{tx('分类','Category')}}<select v-model="form.category" :disabled="!admin"><option value="aluminium">{{tx('铝百叶','Aluminium blinds')}}</option><option value="timber">{{tx('木百叶','Timber blinds')}}</option><option value="composite">{{tx('复合百叶','Composite blinds')}}</option><option value="other">{{tx('其他','Other')}}</option></select></label><div class="field-pair"><label class="catalog-check"><input type="checkbox" v-model="form.published" :disabled="!admin"/>{{tx('在官网展示','Show on website')}}</label><label class="catalog-check"><input type="checkbox" v-model="form.sample" :disabled="!admin"/>{{tx('示例产品','Sample product')}}</label></div></div></div>
<div class="catalog-section"><h3>{{tx('描述与规格','Description and specifications')}}</h3><div class="field-pair"><label>{{tx('中文描述','Chinese description')}}<textarea v-model="form.description_zh" maxlength="3000" :readonly="!admin"/></label><label>{{tx('英文描述','English description')}}<textarea v-model="form.description_en" maxlength="3000" :readonly="!admin"/></label></div><div class="dimension-fields"><label>{{tx('单位','Unit')}}<select v-model="form.unit" :disabled="!admin"><option>mm</option><option>inch</option></select></label><label>{{tx('最小宽度','Minimum width')}}<input v-model.number="form.width_min" type="number" min="0.01" step="any" :readonly="!admin"/></label><label>{{tx('最大宽度','Maximum width')}}<input v-model.number="form.width_max" type="number" min="0.01" step="any" :readonly="!admin"/></label><label>{{tx('最小高度','Minimum height')}}<input v-model.number="form.height_min" type="number" min="0.01" step="any" :readonly="!admin"/></label><label>{{tx('最大高度','Maximum height')}}<input v-model.number="form.height_max" type="number" min="0.01" step="any" :readonly="!admin"/></label></div><div class="field-pair"><label>{{tx('可选颜色 · 用逗号分隔','Colour options · Separate with commas')}}<input v-model="colors" :readonly="!admin"/></label><label>{{tx('控制方式 · 用逗号分隔','Controls · Separate with commas')}}<input v-model="controls" :readonly="!admin"/></label></div><p class="catalog-hint">{{tx('范围可留空，实际项目规格与单价在报价中确认。修改目录不改变历史报价和订单。','Ranges may be left blank. Confirm project specifications and pricing in the quote. Catalogue changes do not alter past quotes or orders.')}}</p></div><div class="catalog-save" v-if="admin"><button type="submit" :disabled="busy">{{busy?tx('保存中…','Saving…'):tx('保存产品','Save product')}}</button><span>{{form.published?tx('保存后供官网展示','Will be visible on the website'):tx('保存为未展示产品','Will remain hidden from the website')}}</span></div></form>
</section><section v-else class="card">{{tx('新增产品或选择一项开始','Add a product or select one to begin')}}</section>
</div>
</template>
<style scoped>
