inmax(0,1fr)}.catalog-overview{grid-template-columns:1fr}.product-photo-preview>img{aspect-ratio:16/7;max-height:230px}.dimension-fields{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:700px){.product-manager{grid-template-columns:1fr}.field-pair{grid-template-columns:1fr}.dimension-fields{grid-template-columns:1fr 1fr}.catalog-save{flex-wrap:wrap;position:static}.catalog-editor,.catalog-list{overflow:visible}}
.product-manager{align-items:start;flex:none}.catalog-list,.catalog-editor{overflow:visible}.gallery-editor{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:14px}.gallery-editor article{border:1px solid #dfe5df;padding:6px;background:white}.gallery-editor article>img{width:100%;aspect-ratio:4/3;object-fit:cover}.gallery-editor article>small{display:block;font-size:10px;color:#617168;margin:4px 0}.gallery-editor article>div{display:flex;flex-wrap:wrap;gap:4px}.gallery-editor button{font-size:10px!important;padding:4px 6px!important;min-height:30px!important}.catalog-save{bottom:0;padding:14px 0;z-index:2;box-shadow:0 -6px 18px rgba(0,0,0,.03)}@media(min-width:1101px){.catalog-list{position:sticky;top:18px}}@media(max-width:700px){.catalog-save{position:sticky;bottom:0}.gallery-editor{grid-template-columns:repeat(3,minmax(0,1fr))}}
.gallery-editor .gallery-thumb{display:block;width:100%;height:auto;aspect-ratio:4/3;padding:0!important;border:2px solid transparent!important;background:white!important;min-height:0!important}.gallery-editor .gallery-thumb.active{border-color:#0f6e5c!important}.gallery-thumb img{display:block;width:100%;height:100%;object-fit:cover}
</style>
